{
  "merchantOrderId": "{{merchant_order_id}}", // auto-generated each run (ORDER_<timestamp>)
  "amount": {{checkout_amount}}, // enter your amount here in paisa (min 100; 10000 = Rs.100)
  "expireAfter": {{expire_after}}, // enter order expiry here in seconds
  "metaInfo": {
    "udf1": "udf1", // optional passthrough fields udf1-udf5
    "udf2": "udf2"
  },
  "paymentFlow": {
    "type": "PG",
    "deviceContext": {
      "deviceOS": "{{device_os}}" // enter device OS here: ANDROID or IOS
    },
    "paymentMode": {
      "type": "UPI_INTENT",
      "targetApp": "{{target_app}}" // enter target UPI app here (Android package e.g. com.phonepe.app; iOS e.g. PHONEPE/GPAY/PAYTM)
    }
  }
}

{
  "merchantOrderId": "{{merchant_order_id}}", // auto-generated each run (ORDER_<timestamp>)
  "amount": {{checkout_amount}}, // enter your amount here in paisa (min 100)
  "expireAfter": {{expire_after}}, // enter order expiry here in seconds
  "metaInfo": {
    "udf1": "udf1", // optional passthrough fields udf1-udf5
    "udf2": "udf2"
  },
  "paymentFlow": {
    "type": "PG",
    "paymentMode": {
      "type": "UPI_COLLECT",
      "details": {
        "type": "VPA", // enter VPA or UPI_NUMBER here
        "vpa": "{{customer_vpa}}" // enter the customer's UPI VPA here (e.g. success@ybl)
      },
      "message": "Payment for order {{merchant_order_id}}" // enter the collect message shown to the payer
    }
  }
}

