}

{
  "merchantOrderId": "{{merchant_order_id}}", // auto-generated each run (ORDER_<timestamp>)
  "amount": {{checkout_amount}}, // enter your amount here in paisa (min 100)
  "expireAfter": {{expire_after}}, // enter order expiry here in seconds
  "metaInfo": {
    "udf1": "udf1", // optional passthrough fields udf1-udf5
    "udf2": "udf2"
  },
  "paymentFlow": {
    "type": "PG",
    "merchantUrls": {
      "redirectUrl": "{{redirect_url}}" // mandatory for CARD - enter your 3DS return URL here
    },
    "paymentMode": {
      "type": "CARD",
      "authMode": "3DS",
      "cardDetails": {
        "encryptedCardNumber": "REPLACE_WITH_RSA_ENCRYPTED_CARD_NUMBER", // enter RSA-4096 encrypted card number here
        "encryptionKeyId": 1, // enter the PhonePe-provided encryption key id here
        "cardHolderName": "{{customer_name}}", // enter the card holder name here
        "expiry": {
          "month": "12", // enter card expiry month (MM)
          "year": "2027" // enter card expiry year (YYYY)
        },
        "encryptedCvv": "REPLACE_WITH_RSA_ENCRYPTED_CVV" // enter RSA-4096 encrypted CVV here
      },
      "merchantUserId": "{{merchant_user_id}}" // enter your internal user id here
    }
  }
}

{
  "merchantOrderId": "{{merchant_order_id}}", // auto-generated each run (ORDER_<timestamp>)
  "amount": {{checkout_amount}}, // enter your amount here in paisa (min 100)
  "expireAfter": {{expire_after}}, // enter order expiry here in seconds
  "metaInfo": {
    "udf1": "udf1", // optional passthrough fields udf1-udf5
    "udf2": "udf2"
  },
  "paymentFlow": {
    "type": "PG",
    "merchantUrls": {
      "redirectUrl": "{{redirect_url}}" // mandatory for NET_BANKING - enter your return URL here
    },
    "paymentMode": {
      "type": "NET_BANKING",
      "bankId": "{{bank_id}}", // enter the bank id here (e.g. HDFC, SBIN)
      "merchantUserId": "{{merchant_user_id}}" // enter your internal user id here
    }
  }
}

{
  "merchantRefundId": "{{merchant_refund_id}}", // auto-generated each run by pre-request script (REFUND_<timestamp>)
  "originalMerchantOrderId": "{{merchant_order_id}}", // enter the original order id to refund here
  "amount": {{refund_amount}} // enter refund amount here in paisa (min 100, must be <= captured amount)
}
